export function addROMPanel({getProject}){
 const anchor=document.getElementById('pico-session-status');if(!anchor)return;
 const chip=getProject().components.find(c=>c.type==='board')?.params.model,newer=chip.startsWith('pico-2'),romSize=newer?32768:16384,revision=newer?'RP2350 A2':'RP2040 B1',flashSize=(newer?4:2)*1024*1024,section=document.createElement('section');
 section.innerHTML='<h3>Özgün ROM · BOOTSEL / flash</h3><p>'+revision+' kodu ayrı bir oturumda gerçekten yürütülür. USB disk okuma ve UF2 üzerinden NOR flash silme/programlama desteklenir. Bu oturum projenin devresine bağlı değildir; flash’ı indirmeden pencereyi kapatırsanız veriler kaybolur. Her oturum bir UF2 yükler; sonraki yükleme için ROM dosyasını yeniden seçin.</p><p>ROM dosyası siteyle dağıtılmaz. Bu profil tam TrustZone / OTP / imzalı açılış veya CYW43 emülasyonu değildir.</p><label>Yerel '+revision+' ROM .bin ('+(romSize/1024)+' KiB) <input data-rom-file type="file" accept=".bin"></label><label>Sektör (LBA) <input data-rom-lba type="number" min="0" max="65535" value="1"></label><button data-rom-command="msc-inquiry" disabled>ROM aygıt bilgisi</button> <button data-rom-command="msc-capacity" disabled>ROM disk kapasitesi</button> <button data-rom-command="msc-read" disabled>ROM sektörü oku</button><label>ROM ile yazılacak UF2 <input data-rom-uf2 type="file" accept=".uf2" disabled></label><button data-rom-export disabled>ROM flash indir</button><pre data-rom-state>Önce doğru ROM dosyasını seçin. Donanım USB aygıtı oluşturulmaz.</pre>';
 anchor.after(section);let worker=null,disposed=false,loaded=false,written=false;
 const state=section.querySelector('[data-rom-state]'),buttons=[...section.querySelectorAll('[data-rom-command]')],uf2=section.querySelector('[data-rom-uf2]'),exportButton=section.querySelector('[data-rom-export]'),romInput=section.querySelector('[data-rom-file]');state.style.whiteSpace='pre-wrap';state.style.overflowWrap='anywhere';
 function busy(value){buttons.forEach(b=>b.disabled=value||!loaded);uf2.disabled=value||!loaded||written;exportButton.disabled=value||!loaded;romInput.disabled=value;}
 const cleanup=()=>{disposed=true;worker?.terminate();worker=null;};const observer=new MutationObserver(()=>{const dialog=section.closest('dialog');if(!section.isConnected||dialog&&!dialog.open){cleanup();observer.disconnect();}});observer.observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:['open']});
 romInput.onchange=async e=>{const f=e.target.files[0];if(!f)return;const project=getProject();busy(true);loaded=false;written=false;try{if(f.size!==romSize)throw Error('ROM dosyası tam '+romSize+' bayt olmalı.');const rom=new Uint8Array(await f.arrayBuffer());if(disposed||getProject()!==project)return;worker?.terminate();worker=new Worker(new URL('./pico-rom-worker.js',import.meta.url),{type:'module'});
  worker.onmessage=({data:d})=>{if(disposed)return;if(d.type==='rom-progress'){state.textContent='Özgün ROM flash yükleme: '+d.done+' / '+d.total+' blok';return;}if(d.type==='rom-error'){state.textContent=d.message;busy(false);return;}if(d.type==='rom-flash'){const url=URL.createObjectURL(new Blob([d.bytes])),a=document.createElement('a');a.href=url;a.download=chip+'-rom-flash.bin';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);busy(false);return;}loaded=true;if(d.lastWrite)written=true;const u=d.usb,t=u.msc;state.textContent=d.revision+' · özgün ROM kodu\nPC 0x'+d.pc.toString(16)+' · '+d.cycles+' çevrim\nUSB '+u.kind+' · '+(u.connected?'bağlı':'bekliyor')+'\nNOR: '+d.nor.erases+' silme / '+d.nor.pages+' program sayfası'+(d.lastWrite?'\nFlash doğrulandı: '+d.lastWrite.bytes+' bayt':'')+(t?'\nSCSI '+t.status+' · '+t.bytes+' bayt\n'+t.hex:'');busy(false);};
  worker.onerror=err=>{state.textContent=err.message;loaded=false;busy(false);cleanup();};state.textContent='Özgün ROM açılıyor…';worker.postMessage({type:'load',chip,rom});
 }catch(err){state.textContent=err.message;busy(false);}e.target.value='';};
 buttons.forEach(button=>button.onclick=()=>{if(!worker)return;busy(true);state.textContent='ROM USB işlemi…';worker.postMessage({type:'command',action:button.dataset.romCommand,lba:Number(section.querySelector('[data-rom-lba]').value)});});
 uf2.onchange=async e=>{const f=e.target.files[0];if(!f||!worker)return;busy(true);try{if(f.size>flashSize*2)throw Error('UF2 dosyası bu kart için çok büyük.');const bytes=new Uint8Array(await f.arrayBuffer());if(disposed)return;state.textContent='Özgün ROM üzerinden flash yazılıyor…';worker.postMessage({type:'write',bytes});}catch(err){state.textContent=err.message;busy(false);}e.target.value='';};
 exportButton.onclick=()=>{if(worker){busy(true);worker.postMessage({type:'export'});}};
}
